        .stream().findFirst().orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));
    if (viewer!=null && interactions.isBlocked(viewer,profile.id())) throw new ResponseStatusException(HttpStatus.NOT_FOUND);
    return profile;
}

